INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $q13${"question":"Hvad er historikernes argument for at atomvaabnene faktisk forhindrede en 3. verdenskrig?","options":["Den gensidige atomtrussel forhindrede direkte stormagtskrig fordi rationelle ledere vidste at en krig ville betyde begge parters undergang — i modsaetning til 1. og 2. verdenskrig hvor magtbalancer kollapsede i regulaer krig","Atomvaabnene forhindrede ikke krig — 3. verdenskrig blev forhindret af FN's fredsbevarende styrker","Atomvaabnene spillede ingen rolle — USA og Sovjet ville aldrig have kaempet direkte mod hinanden","Atomvaabnene forhindrede krig fordi de var for komplekse og dyre til at bruge"],"correct":"Den gensidige atomtrussel forhindrede direkte stormagtskrig fordi rationelle ledere vidste at en krig ville betyde begge parters undergang — i modsaetning til 1. og 2. verdenskrig hvor magtbalancer kollapsede i regulaer krig","accepted_answers":["Den gensidige atomtrussel forhindrede direkte stormagtskrig fordi rationelle ledere vidste at en krig ville betyde begge parters undergang — i modsaetning til 1. og 2. verdenskrig hvor magtbalancer kollapsede i regulaer krig"],"review_text":"Den lange fred — at Vesteuropa ikke oplevede storkrig i 70+ aar — er historisk bemaerkelsesvaerdig. Historikere som John Lewis Gaddis argumenterer at atomafskraekkelse var noeglen. Magtbalancer uden atomvaaben kollapsede to gange paa 30 aar (1914, 1939). Med atomvaaben var prisen for fejlkalkulation saa hoej at rationelle aktorer valgte afspending frem for eskalation. Det er et ubehageligt men empirisk faktum."}$q13$::jsonb,
  'mc','short',$m13${"concepts":["atomafskraekkelse","den lange fred","Gaddis","bipolaritet","stabilitet","MAD"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"analytical_challenge","domain":"cold_war"}$m13$::jsonb,
  'mc_single',4,'auto',true,'cold_war',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $q14${"question":"Hvad er Den Kolde Krigs vigtigste arv i Rusland og den post-sovjetiske verden?","options":["En dyb national ydmygelse over imperiekollapset, mistillid til Vestens intentioner og en politisk kultur der soeger at genvinde stormagts-status — dynamikker der forklarer meget af Ruslands adfaerd efter 1991","Rusland omfavnede fuldt demokrati og markedsoekonomi efter 1991 og Den Kolde Krigs arv er fuldstaendig overvundet","Den Kolde Krig har ingen relevans for nutidigt Rusland — landet er fuldstaendig nyt siden 1991","Rusland er permanent svaekket og kan aldrig igen spille en vigtig rolle i international politik"],"correct":"En dyb national ydmygelse over imperiekollapset, mistillid til Vestens intentioner og en politisk kultur der soeger at genvinde stormagts-status — dynamikker der forklarer meget af Ruslands adfaerd efter 1991","accepted_answers":["En dyb national ydmygelse over imperiekollapset, mistillid til Vestens intentioner og en politisk kultur der soeger at genvinde stormagts-status — dynamikker der forklarer meget af Ruslands adfaerd efter 1991"],"review_text":"Sovjet-sammenbruddet var for mange russere et nationalt traume: imperiet gik tabt, levestandarden kollapsede i 1990'erne, og NATO udvidede sig ostpaa. Putin kaldte sammenbruddet 'det 20. aarhundredes storste geopolitiske katastrofe'. Russisk udenrigspolitik siden 2000 kan forstaaes som forsog paa at genvinde indflydelse: Georgien 2008, Ukraine 2014 og 2022. Den Kolde Krigs arv lever videre i geopolitikkens struktur."}$q14$::jsonb,
  'mc','short',$m14${"concepts":["Rusland","imperial arv","NATO-udvidelse","Putin","ydmygelse","post-sovjet"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"analytical_challenge","domain":"cold_war"}$m14$::jsonb,
  'mc_single',4,'auto',true,'cold_war',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $q15${"question":"Hvad betod Den Kolde Krig for landene i den tredje verden?","options":["Mange udviklingslande blev slagmarker for supermagternes proxy-krige og led enorme menneskelige tab — deres egne politiske valg blev undergravet af supermagt-intervention der prioriterede ideologisk loyalitet over lokal velfaerd","Den tredje verden noed godt af Den Kolde Krig fordi begge supermagter gav generoes bistand uden betingelser","Lande i den tredje verden var uinteressante for supermagterne og fik lov at udvikle sig i fred","Den Kolde Krig styrkede demokrati og stabilitet i de fleste lande i Afrika, Asien og Latinamerika"],"correct":"Mange udviklingslande blev slagmarker for supermagternes proxy-krige og led enorme menneskelige tab — deres egne politiske valg blev undergravet af supermagt-intervention der prioriterede ideologisk loyalitet over lokal velfaerd","accepted_answers":["Mange udviklingslande blev slagmarker for supermagternes proxy-krige og led enorme menneskelige tab — deres egne politiske valg blev undergravet af supermagt-intervention der prioriterede ideologisk loyalitet over lokal velfaerd"],"review_text":"Korea, Vietnam, Angola, Nicaragua, El Salvador, Afghanistan — overalt forsoegte begge supermagter at sikre sig loyale regimer. USA stoettede anti-kommunistiske diktatorer; Sovjet stoettede marxistiske regimer. Chile 1973: CIA stoettede kuppet mod den folkevalgte Allende. Det globale system 1945-89 kostede de fattigste stater uforholdsmaessigt dyrt."}$q15$::jsonb,
  'mc','short',$m15${"concepts":["tredje verden","proxy-krige","CIA","intervention","Chile","menneskelige omkostninger"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"analytical_challenge","domain":"cold_war"}$m15$::jsonb,
  'mc_single',4,'auto',true,'cold_war',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $q16${"question":"Hvad viser Den Kolde Krigs teknologikaploop om sammenhaengen mellem militaer konkurrence og civil teknologiudvikling?","options":["Militaer konkurrence drev teknologiske gennembrud der sidenhen kom civilsamfundet til gode — internettet, GPS og satellitkommunikation stammer direkte fra Cold War-forskning","Al Cold War-teknologisk forskning var hemmeligt militaer og er aldrig delt med offentligheden","Teknologikaplobeet var rent spildt — ingen af opdagelserne har haft civile anvendelser","Kun rumfart-teknologien kom fra Den Kolde Krig — al anden moderne teknologi har andre rodder"],"correct":"Militaer konkurrence drev teknologiske gennembrud der sidenhen kom civilsamfundet til gode — internettet, GPS og satellitkommunikation stammer direkte fra Cold War-forskning","accepted_answers":["Militaer konkurrence drev teknologiske gennembrud der sidenhen kom civilsamfundet til gode — internettet, GPS og satellitkommunikation stammer direkte fra Cold War-forskning"],"review_text":"Internettets forgaenger ARPANET var et amerikansk militaerprojekt. GPS blev udviklet af det amerikanske forsvar. Satellitkommunikation udsprang af rumkaplobeet. Cold War-ressourcerne finansierede grundlaeggende teknologier vi alle bruger dagligt."}$q16$::jsonb,
  'mc','short',$m16${"concepts":["internet","ARPANET","GPS","satellit","teknologispin-off","militaerforskning"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"analytical_challenge","domain":"cold_war"}$m16$::jsonb,
  'mc_single',4,'auto',true,'cold_war',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $q17${"question":"Hvad viste Cuba-krisen om nødvendigheden af direkte kommunikation mellem supermagterne?","options":["Cuba-krisen viste at mangel paa direkte kommunikation oegede atomrisikoen dramatisk — derfor oprettede USA og Sovjet en direkte krisekommunikationslinje (den rode telefon) i 1963","Cuba-krisen viste at supermagterne aldrig behovede direkte kommunikation — diplomater tog altid tid nok","Den rode telefon eksisterede allerede faar Cuba-krisen og spillede en afgørende rolle under selve krisen","Cuba-krisen viste at atomkrig var uundgaaelig og kun ren held forhindrede den"],"correct":"Cuba-krisen viste at mangel paa direkte kommunikation oegede atomrisikoen dramatisk — derfor oprettede USA og Sovjet en direkte krisekommunikationslinje (den rode telefon) i 1963","accepted_answers":["Cuba-krisen viste at mangel paa direkte kommunikation oegede atomrisikoen dramatisk — derfor oprettede USA og Sovjet en direkte krisekommunikationslinje (den rode telefon) i 1963"],"review_text":"Under Cuba-krisen (oktober 1962) tog det timer at sende beskeder via telegram. Som direkte resultat oprettede USA og Sovjet i 1963 en direkte kommunikationslinje. Den rode telefon var teknisk en teletype, ikke en telefon. Den blev brugt under Seksdagskrigen 1967 og Yom Kippur-krigen 1973. Kriser skaber ikke kun risiko men ogsaa institutionelle laeringsresponser."}$q17$::jsonb,
  'mc','short',$m17${"concepts":["rode telefon","Cuba-krisen","krisekommunikation","direkte linje","institutionel laering"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"causal","insight_type":"reframing","challenge_role":"analytical_challenge","domain":"cold_war"}$m17$::jsonb,
  'mc_single',4,'auto',true,'cold_war',7,4
);

