INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $q18${"question":"Var Den Kolde Krig uundgaaelig givet USA og Sovjet's ideologiske og geopolitiske modsaetninger?","options":["Revisionistiske historikere argumenterer at fejltagelser og misforstaaelser spillede en stor rolle — men strukturalisterne svarer at to supermagter med uforenelige ideologier og globale ambitioner naeppe kunne have undgaaet systematisk konfrontation","Den Kolde Krig var 100 procent uundgaaelig fordi kommunisme og kapitalisme er naaturnodvendigt fjendtlige","Den Kolde Krig var fuldt ud undgaaelig — to rationelle statsledere i 1945 var nok til at have forebygget hele konflikten","Sporgsmaalet er rent akademisk og har ingen relevans for nutidige supermagtsforhold"],"correct":"Revisionistiske historikere argumenterer at fejltagelser og misforstaaelser spillede en stor rolle — men strukturalisterne svarer at to supermagter med uforenelige ideologier og globale ambitioner naeppe kunne have undgaaet systematisk konfrontation","accepted_answers":["Revisionistiske historikere argumenterer at fejltagelser og misforstaaelser spillede en stor rolle — men strukturalisterne svarer at to supermagter med uforenelige ideologier og globale ambitioner naeppe kunne have undgaaet systematisk konfrontation"],"review_text":"Ortodokse historikere: Stalins ekspansionisme var uundgaaeligt konfronterende. Revisionistiske: USA's aggressive containment-politik drev konflikten. Post-revisionistiske: begge sider bidrog via misforstaaelse. Strukturalister: bipolaere systemer producerer afskraekkelse men ikke fred. Ingen enkelt faktor forklarer 45 aar med global spaending. Sporgsmaalet paavirker direkte om USA og Kina kan undgaa den samme dynamik."}$q18$::jsonb,
  'mc','short',$m18${"concepts":["uundgaaelighed","revisionisme","strukturalisme","bipolaritet","historikerdebat","USA-Kina"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"cold_war"}$m18$::jsonb,
  'mc_single',5,'auto',true,'cold_war',7,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $q19${"question":"Hvad fortæller Den Kolde Krig om stabiliteten i bipolare magtbalancesystemer sammenlignet med multipolære systemer?","options":["Bipolære systemer kan skabe en form for stabilitet fordi klare alliancer reducerer usikkerhed — men de er skrøbelige fordi eskalation i ét led kan sprede sig globalt og der er ingen tredjepart til at mægle","Bipolære systemer er altid mere stabile end multipolære fordi klare alliancer eliminerer al usikkerhed","Multipolære systemer er altid mere stabile fordi mange aktører balancerer hinanden og ingen enkelt aktør dominerer","Magtbalanceteorier er fuldstændig irrelevante — det var udelukkende ideologi der drev Den Kolde Krig"],"correct":"Bipolære systemer kan skabe en form for stabilitet fordi klare alliancer reducerer usikkerhed — men de er skrøbelige fordi eskalation i ét led kan sprede sig globalt og der er ingen tredjepart til at mægle","accepted_answers":["Bipolære systemer kan skabe en form for stabilitet fordi klare alliancer reducerer usikkerhed — men de er skrøbelige fordi eskalation i ét led kan sprede sig globalt og der er ingen tredjepart til at mægle"],"review_text":"Kenneth Waltz' neorealisme argumenterer at bipolære systemer paradoksalt er mere stabile end multipolære. Men Den Kolde Krig viste ogsaa skrøbelighed: Cuba-krisens naerved-atomkrig og Stanislav Petrovs falske raketvarsel i 1983. Sammenlignet med 1. verdenskrig — et multipolært alliancesystem der kollapsede lynhurtigt — holdt den bipolære orden. Men det er uklogt at se det som systemisk nødvendighed snarere end en kombination af rationelle aktører, held og MAD-logik."}$q19$::jsonb,
  'mc','short',$m19${"concepts":["bipolaritet","multipolaritet","Waltz","neorealisme","magtbalance","stabilitet"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"cold_war"}$m19$::jsonb,
  'mc_single',5,'auto',true,'cold_war',7,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $q20${"question":"Hvad er den analytisk vigtigste lektie Den Kolde Krig giver for forståelsen af nutidens forhold mellem USA og Kina?","options":["Historien viser at en etableret magt og en stigende magt hyppigt ender i konflikt — Den Kolde Krig demonstrerer at dette kan undgås med afskrækkelse og diplomati men kræver institutionelle kanaler og aktiv kriseforebyggelse","Den Kolde Krig viser at USA altid vinder og Kina vil kollapse ligesom Sovjet gjorde","Den Kolde Krig er fuldstændig irrelevant for USA-Kina-forholdet fordi situationen er fundamentalt anderledes","Den vigtigste lektie er at militær oprustning altid er den bedste løsning mod en rivaliserende supermagt"],"correct":"Historien viser at en etableret magt og en stigende magt hyppigt ender i konflikt — Den Kolde Krig demonstrerer at dette kan undgås med afskrækkelse og diplomati men kræver institutionelle kanaler og aktiv kriseforebyggelse","accepted_answers":["Historien viser at en etableret magt og en stigende magt hyppigt ender i konflikt — Den Kolde Krig demonstrerer at dette kan undgås med afskrækkelse og diplomati men kræver institutionelle kanaler og aktiv kriseforebyggelse"],"review_text":"Graham Allison identificerede at ud af 16 historiske tilfaelde hvor en stigende magt udfordrede en etableret magt, endte 12 i krig — Thukydides-faelden. Den Kolde Krig er et af de 4 der undgik krig. Lektionerne: institutionelle kommunikationskanaler, krisehåndtering ved Cuba, klare rode linjer og gensidig afskraekkelse forhindrede det vaerste. Den vigtigste lektie er at undgaaelse kraever aktivt institutionelt arbejde og vilje til diplomati."}$q20$::jsonb,
  'mc','short',$m20${"concepts":["Thukydides-faelde","USA-Kina","Allison","stigende magt","diplomati","kriseforebyggelse"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"cold_war"}$m20$::jsonb,
  'mc_single',5,'auto',true,'cold_war',7,5
);;
